// src/tools/execution.tools.ts
var backend = z5.enum(["live", "paper"]).optional().describe("Execution backend for this call; default is the gateway's default backend");
var intentId = z5.string().min(1).optional().describe(
  "Idempotency key. Re-submitting the same intentId returns the original execution instead of placing a second order. Recommended for any retry loop."
);
function executionTools(gateway, client) {
  return [
    {
      name: "execution_place_order",
      description: "Place an order through the execution gateway: idempotent (retry with the same intentId returns the original execution), reconciled on ambiguous failures, and routable to the live exchange or the paper simulator via `backend`. Paper orders need no API keys. MARKET and LIMIT types supported on paper.",
      inputSchema: orderParamsSchema.extend({ intentId, backend }),
      handler: async (args) => {
        const { intentId: intent, backend: route } = args;
        return textResult(
          await gateway.placeOrder(
            { ...args, intentId: intent, symbol: normalizeSymbol(args.symbol) },
            { backend: route }
          )
        );
      }
    },
    {
      name: "execution_cancel_order",
      description: "Cancel an order idempotently by exchange orderId, clientOrderId, or the intentId from execution_place_order. Cancels of already-gone orders resolve to a terminal CANCELED execution (never a thrown -2011).",
      inputSchema: z5.object({
        symbol: z5.string().min(1).describe("USD-M pair, e.g. BTCUSDT"),
        orderId: z5.number().int().positive().optional().describe("Exchange order id"),
        origClientOrderId: z5.string().optional().describe("Client order id (the reconciliation key)"),
        intentId,
        backend
      }),
      handler: async ({ symbol: symbol3, orderId, origClientOrderId, intentId: intent, backend: route }) => textResult(
        await gateway.cancelOrder(
          normalizeSymbol(symbol3),
          { orderId, origClientOrderId, intentId: intent, backend: route }
        )
      )
    },
    {
      name: "execution_get_order",
      description: "Fetch an execution from the ledger by its intentId. When `backend` is omitted both ledgers are searched (paper first), so callers do not need to remember where an intent ran.",
      inputSchema: z5.object({ intentId: z5.string().min(1), backend }),
      handler: async ({ intentId: intent, backend: route }) => {
        const execution = route ? gateway.getExecution(intent, route) : gateway.getExecution(intent, "paper") ?? gateway.getExecution(intent, "live");
        if (!execution) throw new Error(`No execution for intentId ${intent}`);
        return textResult(execution);
      }
    },
    {
      name: "execution_list_orders",
      description: "List the execution ledger (most recent first) for a backend. Each entry carries status, fills, and reconciliation state. Paper and live ledgers are independent.",
      inputSchema: z5.object({ backend }),
      handler: async ({ backend: route }) => textResult(gateway.listExecutions(route))
    },
    {
      name: "execution_reconcile_order",
      description: "Force a reconciliation pass for an intent whose outcome is unknown (e.g. after a timeout). Recovers the true state from the exchange (live) or simulator (paper) instead of guessing.",
      inputSchema: z5.object({ intentId: z5.string().min(1), backend }),
      handler: async ({ intentId: intent, backend: route }) => textResult(await gateway.reconcile(intent, route))
    },
    {
      name: "execution_status",
      description: "Snapshot of the execution environment: default backend, risk-gateway state (when a trading policy is configured), and the paper simulator account (balance, positions, unrealized PnL). Read-only, never places orders.",
      inputSchema: z5.object({}),
      handler: async () => {
        const risk = client?.getRiskStatus?.();
        const paper = gateway.paperEngine.getAccountInfo();
        return textResult({
          defaultBackend: gateway.backend,
          risk: risk ?? null,
          paper: {
            balance: paper.balance,
            availableBalance: paper.availableBalance,
            totalWalletBalance: paper.totalWalletBalance,
            unrealizedPnl: paper.unrealizedPnl,
            realizedPnl: paper.realizedPnl,
            positions: Object.values(paper.positions).filter((p) => p.quantity > 0),
            orderCount: paper.orders.length
          }
        });
      }
    }
  ];
}

